-- Optional stewardship of repository-seeded reference tables.
UPDATE CFG_TASKS SET TARGET_TABLE_ID=(SELECT TABLE_ID FROM CFG_TABLES WHERE SCHEMA_NAME='ds' AND TABLE_NAME='agents') WHERE TASK_CODE='merge' AND PIPELINE_ID=(SELECT PIPELINE_ID FROM CFG_PIPELINES WHERE PIPELINE_CODE='SI_STEWARD_DS_AGENTS');
UPDATE CFG_TASKS SET TARGET_TABLE_ID=(SELECT TABLE_ID FROM CFG_TABLES WHERE SCHEMA_NAME='ds' AND TABLE_NAME='support_areas') WHERE TASK_CODE='merge' AND PIPELINE_ID=(SELECT PIPELINE_ID FROM CFG_PIPELINES WHERE PIPELINE_CODE='SI_STEWARD_DS_SUPPORT_AREAS');
UPDATE CFG_TASKS SET TARGET_TABLE_ID=(SELECT TABLE_ID FROM CFG_TABLES WHERE SCHEMA_NAME='ds' AND TABLE_NAME='customer_types') WHERE TASK_CODE='merge' AND PIPELINE_ID=(SELECT PIPELINE_ID FROM CFG_PIPELINES WHERE PIPELINE_CODE='SI_STEWARD_DS_CUSTOMER_TYPES');

SELECT t.TASK_ID,'SCHEMA_EVOLUTION','true' FROM CFG_TASKS t JOIN CFG_PIPELINES p ON p.PIPELINE_ID=t.PIPELINE_ID WHERE p.PIPELINE_CODE='SUPPORT_DM' AND t.TASK_CODE='agents';
UPDATE CFG_TASK_PARAMETERS SET PARAMETER_VALUE='SELECT agent_code, agent_name, team, email, CAST(NULL AS BIGINT) AS UPLOAD_ID FROM lnd.agents WHERE left_company = ''N'''
WHERE PARAMETER_NAME='SELECT_QUERY' AND TASK_ID=(SELECT t.TASK_ID FROM CFG_TASKS t JOIN CFG_PIPELINES p ON p.PIPELINE_ID=t.PIPELINE_ID WHERE p.PIPELINE_CODE='SUPPORT_DM' AND t.TASK_CODE='agents');
